function initmap(){var myMap,objects,balloons;myMap=new ymaps.Map("map",{center:[54.828653710193066,56.410488536701195],controls:[],zoom:9});objects=ymaps.geoQuery(ymaps.geocode("Уфа, с. Иглино, ул. Горького, 75",{results:1})).addToMap(myMap);balloons=["Твой стоматолог"],i=0;objects.then(function(){objects.each(function(object){object.properties.set("iconCaption",balloons[i++]);object.options.set("preset","islands#darkBlueDotIconWithCaption")});myMap.setBounds(objects.getBounds(),{checkZoomRange:true,zoomMargin:[20,20,20,20]}).then(function(){myMap.setZoom(16)})})}